{"path":"/tmp/sv-a5178b02eaac4720a03573857d52812d/eng/install-sdk.ps1","file_text":"#!/usr/bin/env pwsh
<#
.SYNOPSIS
    Installs the .NET SDK required by this repository into the repo-local .dotnet/ directory.
    The version is read from global.json so there is a single source of truth.
#>

$ErrorActionPreference = 'Stop'

$repoRoot   = Split-Path -Parent $PSScriptRoot
$installDir = Join-Path $repoRoot '.dotnet'
$globalJson = Get-Content (Join-Path $repoRoot 'global.json') -Raw | ConvertFrom-Json
$sdkVersion = $globalJson.sdk.version

if (-not $sdkVersion) {
    Write-Error "Could not read sdk.version from global.json"
    exit 1
}

Write-Host "Installing .NET SDK $sdkVersion to $installDir ..."

$installScript = Join-Path $repoRoot 'eng' 'dotnet-install.ps1'

try {
    Invoke-WebRequest -Uri 'https://dot.net/v1/dotnet-install.ps1' -OutFile $installScript -UseBasicParsing

    & $installScript -Version $sdkVersion -InstallDir $installDir
} finally {
    Remove-Item $installScript -ErrorAction SilentlyContinue
}

Write-Host ''
Write-Host 'Done. Activate this SDK in your current session:'
Write-Host ''
if ($IsWindows -or (-not (Get-Variable IsWindows -ErrorAction SilentlyContinue))) {
    Write-Host "  `$env:DOTNET_ROOT = '$installDir'"
    Write-Host "  `$env:PATH        = `"$installDir;`$env:PATH`""
} else {
    Write-Host "  export DOTNET_ROOT='$installDir'"
    Write-Host "  export PATH='$installDir':\""\$PATH"\"
}
Write-Host ''
"}

